/**
 * Unified Harness Protocol — the specification, as data.
 *
 * Every constant here is transcribed from UHP 2026-08-11. Nothing in this package talks to a
 * network: it exists so that a client, a server, or a test suite can agree on the vocabulary
 * without each one retyping it out of the prose and getting a string subtly wrong.
 *
 * Spec: https://github.com/HarnessRouter/harnessrouter/tree/main/protocol
 */

/** The protocol version this package describes. UHP versions are dates, and they sort. */
export const PROTOCOL_VERSION = '2026-08-11';

/** The header a client sends to ask for a version, and a server sets on every response. */
export const VERSION_HEADER = 'UHP-Version';

/** Conformance classes, weakest first. Each one includes the one before it. */
export const CONFORMANCE_CLASSES = ['core', 'extended', 'full'];

/**
 * Capability keys from the discovery document. A server reports every one of these as a
 * boolean; an absent key MUST be read as `false`.
 */
export const CAPABILITIES = [
  'streaming',
  'sessions',
  'cancellation',
  'files_input',
  'files_output',
  'session_listing',
  'harness_management',
  'session_sharing',
  'idempotency',
];

/** Capabilities a server MUST implement to claim each class. */
export const CLASS_CAPABILITIES = {
  core: ['streaming', 'sessions', 'cancellation'],
  extended: ['streaming', 'sessions', 'cancellation', 'files_input', 'files_output', 'session_listing'],
  full: [
    'streaming',
    'sessions',
    'cancellation',
    'files_input',
    'files_output',
    'session_listing',
    'harness_management',
    'session_sharing',
  ],
};

/** Task states. */
export const TASK_STATUS = {
  IN_PROGRESS: 'in_progress',
  COMPLETED: 'completed',
  FAILED: 'failed',
  INCOMPLETE: 'incomplete',
  CANCELLED: 'cancelled',
};

/** The four states a task never leaves once it arrives. */
export const TERMINAL_STATUSES = ['completed', 'failed', 'incomplete', 'cancelled'];

/** Id prefixes, so an identifier is never ambiguous about what it points at. */
export const ID_PREFIXES = {
  chrn_: 'harness',
  resp_: 'response',
  hsess: 'session',
  file_: 'file',
  cntr_: 'container',
};

/** The streaming event vocabulary. Events describe what happened, never how to display it. */
export const EVENTS = {
  CREATED: 'response.created',
  IN_PROGRESS: 'response.in_progress',
  COMPLETED: 'response.completed',
  INCOMPLETE: 'response.incomplete',
  FAILED: 'response.failed',
  OUTPUT_ITEM_ADDED: 'response.output_item.added',
  OUTPUT_ITEM_DONE: 'response.output_item.done',
  CONTENT_PART_ADDED: 'response.content_part.added',
  CONTENT_PART_DONE: 'response.content_part.done',
  OUTPUT_TEXT_DELTA: 'response.output_text.delta',
  OUTPUT_TEXT_DONE: 'response.output_text.done',
  ANNOTATION_ADDED: 'response.output_text.annotation.added',
  REASONING_PART_ADDED: 'response.reasoning_summary_part.added',
  REASONING_TEXT_DELTA: 'response.reasoning_summary_text.delta',
  REASONING_PART_DONE: 'response.reasoning_summary_part.done',
  FUNCTION_CALL_ARGUMENTS_DELTA: 'response.function_call_arguments.delta',
  FUNCTION_CALL_ARGUMENTS_DONE: 'response.function_call_arguments.done',
  ERROR: 'error',
};

/** Exactly one of these ends a stream. */
export const TERMINAL_EVENTS = [EVENTS.COMPLETED, EVENTS.INCOMPLETE, EVENTS.FAILED];

/** Output item types a response may carry. A client MUST tolerate ones it does not know. */
export const OUTPUT_ITEM_TYPES = ['message', 'reasoning', 'function_call', 'function_call_output'];

/** Broad error classes, and the HTTP statuses each covers. */
export const ERROR_TYPES = {
  invalid_request_error: [400, 404, 409, 413, 422],
  authentication_error: [401],
  permission_error: [403],
  rate_limit_error: [429],
  harness_error: [200],
  server_error: [500, 502, 503, 504],
};

/** The closed set of error codes, with the status each is reported under. */
export const ERROR_CODES = {
  unsupported_protocol_version: 400,
  invalid_input: 400,
  harness_not_found: 404,
  response_not_found: 404,
  session_not_found: 404,
  file_not_found: 404,
  session_expired: 404,
  harness_mismatch: 409,
  session_busy: 409,
  file_too_large: 413,
  model_unavailable: 422,
  unsupported_base: 422,
  missing_credential: 401,
  invalid_credential: 401,
  insufficient_scope: 403,
  rate_limited: 429,
  quota_exhausted: 429,
  harness_error: 200,
  harness_unavailable: 503,
  provider_error: 200,
  timeout: 200,
  cancelled: 200,
  preview_unavailable: 501,
  preview_failed: 502,
};

/** Codes worth retrying. Everything absent from this list is not. */
export const RETRYABLE_CODES = ['rate_limited', 'session_busy', 'harness_unavailable'];

/** Endpoint paths, so a client does not spell one of them wrong. */
export const ENDPOINTS = {
  discovery: '/v1/uhp',
  harnesses: '/v1/harnesses',
  harness: (id) => `/v1/harnesses/${id}`,
  harnessModels: (id) => `/v1/harnesses/${id}/models`,
  harnessEvents: (id) => `/v1/harnesses/${id}/events`,
  models: '/v1/models',
  responses: '/v1/responses',
  response: (id) => `/v1/responses/${id}`,
  responseInputItems: (id) => `/v1/responses/${id}/input_items`,
  responseCancel: (id) => `/v1/responses/${id}/cancel`,
  sessions: '/v1/sessions',
  session: (id) => `/v1/sessions/${id}`,
  sessionTurns: (id) => `/v1/sessions/${id}/turns`,
  sessionFiles: (id) => `/v1/sessions/${id}/files`,
  sessionCancel: (id) => `/v1/sessions/${id}/cancel`,
  sessionShare: (id) => `/v1/sessions/${id}/share`,
  sessionDelete: (id) => `/v1/traces/${id}`,
  files: '/v1/files',
  fileContent: (containerId, fileId) => `/v1/containers/${containerId}/files/${fileId}/content`,
};

/** True when a task will never change state again. */
export function isTerminal(status) {
  return TERMINAL_STATUSES.includes(status);
}

/**
 * True when retrying is worth anything.
 *
 * `quota_exhausted` is deliberately excluded even though it is a 429: nothing changes until the
 * quota does, so a retry is only load.
 */
export function isRetryable({ code, type, status } = {}) {
  if (code && RETRYABLE_CODES.includes(code)) return true;
  if (code === 'quota_exhausted') return false;
  if (type === 'server_error') return true;
  if (typeof status === 'number' && status >= 500 && status <= 504) return true;
  return false;
}

/** What kind of object an id points at, or null when the prefix is unknown. */
export function objectTypeForId(id) {
  if (typeof id !== 'string') return null;
  for (const [prefix, type] of Object.entries(ID_PREFIXES)) {
    if (id.startsWith(prefix)) return type;
  }
  return null;
}

/**
 * Check a discovery document against its own class claim.
 *
 * A class claim that contradicts the capability list tells a client two different things, so it
 * is worth checking before you trust either.
 */
export function checkDiscovery(doc) {
  const problems = [];
  if (!doc || typeof doc !== 'object') return { ok: false, problems: ['discovery document is not an object'] };
  if (doc.protocol !== 'uhp') problems.push(`protocol is ${JSON.stringify(doc.protocol)}, expected "uhp"`);
  if (!Array.isArray(doc.versions) || doc.versions.length === 0) problems.push('versions is missing or empty');
  else if (doc.default_version && !doc.versions.includes(doc.default_version)) {
    problems.push(`default_version ${doc.default_version} is not in versions`);
  }
  const cls = doc.conformance_class;
  if (!CONFORMANCE_CLASSES.includes(cls)) problems.push(`conformance_class ${JSON.stringify(cls)} is not a known class`);
  else {
    const caps = doc.capabilities || {};
    for (const required of CLASS_CAPABILITIES[cls]) {
      if (caps[required] !== true) problems.push(`class ${cls} requires capability ${required}, which is not true`);
    }
  }
  return { ok: problems.length === 0, problems };
}

/**
 * Find gaps in a stream's sequence numbers.
 *
 * `sequence_number` starts at 0 and increases by exactly 1, which is the whole point of it: a
 * client can tell a dropped event from a quiet agent.
 */
export function checkSequence(events) {
  const seen = new Set();
  for (const event of events) {
    if (event && typeof event.sequence_number === 'number') seen.add(event.sequence_number);
  }
  if (seen.size === 0) return { ok: true, missing: [] };
  const highest = Math.max(...seen);
  const missing = [];
  for (let n = 0; n <= highest; n++) if (!seen.has(n)) missing.push(n);
  return { ok: missing.length === 0, missing };
}

export default {
  PROTOCOL_VERSION,
  VERSION_HEADER,
  CONFORMANCE_CLASSES,
  CLASS_CAPABILITIES,
  CAPABILITIES,
  TASK_STATUS,
  TERMINAL_STATUSES,
  ID_PREFIXES,
  EVENTS,
  TERMINAL_EVENTS,
  OUTPUT_ITEM_TYPES,
  ERROR_TYPES,
  ERROR_CODES,
  RETRYABLE_CODES,
  ENDPOINTS,
  isTerminal,
  isRetryable,
  objectTypeForId,
  checkDiscovery,
  checkSequence,
};
